from pathlib import Path
from datetime import datetime
import os, re, shutil, hashlib, mimetypes, sys

pictures = Path.home() / "Pictures"
source = pictures / "photos"
if not source.is_dir():
    source = pictures

organized = source / "Organized"
report = organized / "_organization_report.txt"

image_exts = {'.jpg','.jpeg','.png','.gif','.bmp','.tif','.tiff','.heic','.heif','.webp','.raw','.cr2','.nef','.arw','.orf','.rw2','.dng','.psd'}
video_exts = {'.mov','.mp4','.m4v','.avi','.mkv','.wmv','.mpg','.mpeg','.3gp','.webm'}
media_exts = image_exts | video_exts

def safe_dest(path: Path) -> Path:
    if not path.exists():
        return path
    stem, suffix = path.stem, path.suffix
    parent = path.parent
    i = 1
    while True:
        candidate = parent / f"{stem}_{i:03d}{suffix}"
        if not candidate.exists():
            return candidate
        i += 1

def file_hash(p: Path, chunk=1024*1024):
    h = hashlib.sha256()
    with p.open('rb') as f:
        while True:
            b = f.read(chunk)
            if not b:
                break
            h.update(b)
    return h.hexdigest()

def exif_date(p: Path):
    try:
        from PIL import Image, ExifTags
        with Image.open(p) as img:
            exif = getattr(img, "_getexif", lambda: None)()
            if not exif:
                return None
            for tag in (36867, 36868, 306):  # DateTimeOriginal, DateTimeDigitized, DateTime
                val = exif.get(tag)
                if val:
                    if isinstance(val, bytes):
                        val = val.decode(errors='ignore')
                    val = str(val).strip()
                    for fmt in ("%Y:%m:%d %H:%M:%S", "%Y-%m-%d %H:%M:%S"):
                        try:
                            return datetime.strptime(val[:19], fmt)
                        except Exception:
                            pass
    except Exception:
        return None
    return None

date_patterns = [
    re.compile(r'(?<!\d)(20\d{2}|19\d{2})[-_. ]?([01]\d)[-_. ]?([0-3]\d)(?!\d)'),
    re.compile(r'(?<!\d)([01]\d)[-_. ]?([0-3]\d)[-_. ]?(20\d{2}|19\d{2})(?!\d)'),
]

def filename_date(p: Path):
    s = p.name
    for rx in date_patterns:
        m = rx.search(s)
        if not m:
            continue
        parts = m.groups()
        if len(parts[0]) == 4:
            y, mo, d = parts
        else:
            mo, d, y = parts
        try:
            return datetime(int(y), int(mo), int(d))
        except Exception:
            pass
    return None

def best_date(p: Path):
    dt = None
    if p.suffix.lower() in image_exts:
        dt = exif_date(p)
    if not dt:
        dt = filename_date(p)
    if not dt:
        dt = datetime.fromtimestamp(p.stat().st_mtime)
    return dt

organized.mkdir(exist_ok=True)
seen = {}
moved = []
dupes = []
skipped = []

# Include hashes for already organized files, so re-running is safe.
for p in organized.rglob('*'):
    if p.is_file() and p.suffix.lower() in media_exts:
        try:
            seen[file_hash(p)] = p
        except Exception:
            pass

for p in list(source.rglob('*')):
    if not p.is_file():
        continue
    try:
        p.relative_to(organized)
        continue
    except ValueError:
        pass
    if p.name.startswith('.'):
        skipped.append((str(p), 'hidden/system file'))
        continue
    ext = p.suffix.lower()
    if ext not in media_exts:
        skipped.append((str(p), 'not a recognized photo/video file'))
        continue

    try:
        h = file_hash(p)
        if h in seen:
            dt = best_date(p)
            category = 'Duplicate_Photos' if ext in image_exts else 'Duplicate_Videos'
            dest_dir = organized / category / f"{dt.year:04d}" / f"{dt.year:04d}-{dt.month:02d}"
            dest_dir.mkdir(parents=True, exist_ok=True)
            dest = safe_dest(dest_dir / p.name)
            shutil.move(str(p), str(dest))
            dupes.append((str(p), str(dest), str(seen[h])))
            continue
        seen[h] = p

        dt = best_date(p)
        category = 'Photos' if ext in image_exts else 'Videos'
        dest_dir = organized / category / f"{dt.year:04d}" / f"{dt.year:04d}-{dt.month:02d}"
        dest_dir.mkdir(parents=True, exist_ok=True)
        dest = safe_dest(dest_dir / p.name)
        shutil.move(str(p), str(dest))
        moved.append((str(p), str(dest)))
    except Exception as e:
        skipped.append((str(p), f'error: {e}'))

with report.open('w', encoding='utf-8') as f:
    f.write(f"Photo organization report\n")
    f.write(f"Source: {source}\n")
    f.write(f"Organized folder: {organized}\n")
    f.write(f"Run time: {datetime.now().isoformat(timespec='seconds')}\n\n")
    f.write(f"Moved media files: {len(moved)}\n")
    f.write(f"Duplicates moved aside, not deleted: {len(dupes)}\n")
    f.write(f"Skipped files: {len(skipped)}\n\n")
    if moved:
        f.write("Moved:\n")
        for a,b in moved:
            f.write(f"  {a} -> {b}\n")
    if dupes:
        f.write("\nDuplicates:\n")
        for a,b,orig in dupes:
            f.write(f"  {a} -> {b}  duplicate of {orig}\n")
    if skipped:
        f.write("\nSkipped:\n")
        for a,why in skipped:
            f.write(f"  {a} ({why})\n")

print(f"Source: {source}")
print(f"Organized into: {organized}")
print(f"Moved media files: {len(moved)}")
print(f"Duplicates moved aside (not deleted): {len(dupes)}")
print(f"Skipped non-media/errors: {len(skipped)}")
print(f"Report: {report}")
